// NEXUS PROTOCOL: Parseador + Interceptor de Reservas v2
const items = $input.all();

for (const item of items) {
  let rawOutput = item.json.output || item.json.text || "";
  let parsedMessages = [];
  let reservaData = null;

  if (typeof rawOutput === 'string') {
    rawOutput = rawOutput.replace(/```json/gi, "").replace(/```/g, "").trim();
  }

  function extractJsonFromString(str) {
    const jsonMatch = str.match(/\{[\s\S]*\}/s);
    if (jsonMatch) {
      try {
        return JSON.parse(jsonMatch[0]);
      } catch(e) {
        return null;
      }
    }
    return null;
  }

  try {
    let jsonData = typeof rawOutput === 'string' ? JSON.parse(rawOutput) : rawOutput;
    if (jsonData.messages && Array.isArray(jsonData.messages)) {
      parsedMessages = jsonData.messages.map(m => m.text || m.mensaje || "");
    } else {
      parsedMessages = [rawOutput];
    }
    if (jsonData.reserva && jsonData.reserva.email) {
      reservaData = jsonData.reserva;
    }
  } catch (error) {
    if (typeof rawOutput === 'string') {
      const extracted = extractJsonFromString(rawOutput);
      if (extracted) {
        if (extracted.messages && Array.isArray(extracted.messages)) {
          parsedMessages = extracted.messages.map(m => m.text || m.mensaje || "");
        } else {
          parsedMessages = [rawOutput];
        }
        if (extracted.reserva && extracted.reserva.email) {
          reservaData = extracted.reserva;
        }
      } else {
        parsedMessages = [rawOutput];
      }
    } else {
      parsedMessages = [rawOutput];
    }
  }

  item.json.mensaje_1 = parsedMessages[0] || "";
  item.json.mensaje_2 = parsedMessages[1] || "";
  item.json.mensaje_3 = parsedMessages[2] || "";
  item.json.datos_reserva = reservaData;
  delete item.json.output;
}

return items;

