// NEXUS PROTOCOL: Parseador para Mensajes en Partes - PRODUCTION READY
// El telefono se obtiene de Edit Fields2 (que lo extrae del WhatsApp Trigger)
// En ejecucion real, todos los nodos previos ya corrieron y sus datos estan disponibles
const items = $input.all();
const newItems = [];

// FUENTE 1: Edit Fields2 ya tiene TELEFONO = contacts[0].wa_id del WhatsApp Trigger
// En run real esto funciona porque Edit Fields2 ya ejecuto antes
let telefonoFinal = '';
try {
  telefonoFinal = String($('Edit Fields2').first().json.TELEFONO || '').trim();
} catch(e) { telefonoFinal = ''; }

// FUENTE 2: WhatsApp Trigger1 directamente
if (!telefonoFinal) {
  try {
    const t = $('WhatsApp Trigger1').first().json;
    telefonoFinal = String(
      t?.contacts?.[0]?.wa_id ||
      t?.messages?.[0]?.from ||
      ''
    ).trim();
  } catch(e) { telefonoFinal = ''; }
}

// FUENTE 3: Buscar en los items del input actual
if (!telefonoFinal) {
  for (const it of items) {
    const v = it.json.TELEFONO || it.json.telefono || it.json.wa_id || it.json.from;
    if (v && String(v).trim()) { telefonoFinal = String(v).trim(); break; }
  }
}

// Funcion auxiliar para extraer JSON embebido en strings
function extractJson(str) {
  const m = str.match(/\{[\s\S]*\}/s);
  if (m) { try { return JSON.parse(m[0]); } catch(e) { return null; } }
  return null;
}

for (const item of items) {
  const rawOutputRaw = item.json.output || item.json.text;
  if (!rawOutputRaw) continue;

  let rawOutput = String(rawOutputRaw).replace(/```json/gi, '').replace(/```/g, '').trim();
  let parsedMessages = [];

  try {
    const jsonData = JSON.parse(rawOutput);
    if (jsonData && Array.isArray(jsonData.messages)) {
      parsedMessages = jsonData.messages.map(m => String(m.text || m.mensaje || '')).filter(Boolean);
    } else {
      parsedMessages = [rawOutput];
    }
  } catch (e) {
    const extracted = extractJson(rawOutput);
    if (extracted && Array.isArray(extracted.messages)) {
      parsedMessages = extracted.messages.map(m => String(m.text || m.mensaje || '')).filter(Boolean);
    } else {
      parsedMessages = [rawOutput];
    }
  }

  if (parsedMessages.length === 0) parsedMessages = [rawOutput];

  const baseDelay = item.json.delay || 1500;

  for (let i = 0; i < parsedMessages.length; i++) {
    newItems.push({
      json: {
        ...item.json,
        telefono: telefonoFinal,
        text_to_send: parsedMessages[i],
        delay_seconds: i === 0 ? 0 : baseDelay,
        message_index: i + 1,
        total_messages: parsedMessages.length
      }
    });
  }
}

return newItems;

const src = $('📤 Redis - Leer Buffer').first().json.buffer_messages;
let msgs = [];
if (Array.isArray(src)) msgs = src;
else if (src !== undefined && src !== null && src !== '') msgs = [src];
let combinado = msgs
  .map(m => (typeof m === 'string' ? m : JSON.stringify(m)))
  .map(s => s.trim())
  .filter(s => s !== '')
  .join('\n');
if (!combinado) combinado = $('Edit Fields4').first().json.msg_text || '';
return [{ json: { mensaje_combinado: combinado } }];
